import numpy as np
from scipy.optimize import minimize

def f(vars):
    x, y, z = vars
    if x <= 0 or y <= 0 or z <= 0:
        return 1e18
    return (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1) / (x*y + y*z + z*x)

best_f = 1e18
for _ in range(100):
    start_point = np.random.rand(3) * 5
    res = minimize(f, start_point, bounds=[(1e-6, None), (1e-6, None), (1e-6, None)])
    if res.fun < best_f:
        best_f = res.fun
        print(f"New minimum: {best_f} at {res.x}")

print(f"Final best_f: {best_f}")

